/bin/zsh -lc "python3 -B -c 'from pathlib import Path
import sqlite3

namespace = {}
exec(compile(Path(\"project/consumer.py\").read_text(), \"project/consumer.py\", \"exec\"), namespace)
original = namespace[\"consume\"]

class DB:
    def __init__(self):
        self.conn = sqlite3.connect(\":memory:\")
        self.conn.executescript(\"\"\"
            CREATE TABLE accounts(account_id TEXT PRIMARY KEY, revision INTEGER, tier TEXT);
            CREATE TABLE audits(event_id TEXT);
        \"\"\")
    def transaction(self):
        return self.conn
    def set_account(self, account, revision, tier):
        self.conn.execute(\"\"\"INSERT INTO accounts VALUES (?, ?, ?)
            ON CONFLICT(account_id) DO UPDATE SET revision=excluded.revision, tier=excluded.tier\"\"\",
            (account, revision, tier))
    def insert_audit(self, event_id):
        self.conn.execute(\"INSERT INTO audits VALUES (?)\", (event_id,))
    def result(self):
        return {\"accounts\": self.conn.execute(\"SELECT * FROM accounts\").fetchall(),
                \"audits\": self.conn.execute(\"SELECT event_id FROM audits\").fetchall()}

class Delivery:
    def __init__(self, fail_ack=False):
        self.fail_ack = fail_ack
        self.acked = False
    def ack(self):
        if self.fail_ack:
            raise ConnectionError(\"injected loss at acknowledgement boundary\")
        self.acked = True

history = [
    dict(event_id=\"e12\", account_id=\"a\", revision=12, tier=\"gold\"),
    dict(event_id=\"e12\", account_id=\"a\", revision=12, tier=\"gold\"),
    dict(event_id=\"e11\", account_id=\"a\", revision=11, tier=\"silver\"),
]

def guarded(event, db, delivery):
    with db.transaction():
        applied = db.conn.execute(\"\"\"INSERT INTO accounts VALUES (?, ?, ?)
            ON CONFLICT(account_id) DO UPDATE SET revision=excluded.revision, tier=excluded.tier
            WHERE accounts.revision < excluded.revision
            RETURNING account_id\"\"\",
            (event[\"account_id\"], event[\"revision\"], event[\"tier\"])).fetchone()
        if applied:
            db.insert_audit(event[\"event_id\"])
    delivery.ack()

for label, consumer in [(\"supplied consumer\", original), (\"atomic newer-only model\", guarded)]:
    db = DB()
    for event in history:
        consumer(event, db, Delivery())
    print(label, db.result())
    db = DB()
    try:
        consumer(history[0], db, Delivery(fail_ack=True))
    except ConnectionError:
        pass
    for event in history:
        consumer(event, db, Delivery())
    print(label + \" / commit then lost ACK and replay\", db.result())

db = DB()
db.conn.execute(\"CREATE TRIGGER fail_audit BEFORE INSERT ON audits BEGIN SELECT RAISE(ABORT, '\\''injected audit failure'\\''); END\")
delivery = Delivery()
try:
    guarded(history[0], db, delivery)
except sqlite3.IntegrityError:
    pass
assert db.result() == {\"accounts\": [], \"audits\": []}
assert not delivery.acked
db.conn.execute(\"DROP TRIGGER fail_audit\")
guarded(history[0], db, Delivery())
assert db.result() == {\"accounts\": [(\"a\", 12, \"gold\")], \"audits\": [(\"e12\",)]}
print(\"atomic newer-only model / audit failure: full rollback, no ACK, retry applies once\")
print(\"SQLite runtime:\", sqlite3.sqlite_version)
'"
